SELECT country_group, signup_quarter, row_count, consumer_count FROM (SELECT CASE WHEN country IN ('DE', 'UK') THEN 'group_a' ELSE 'other' END AS country_group, QUARTER(signup_date) AS signup_quarter, COUNT(*) AS row_count, COUNT(CASE WHEN segment = 'Consumer' THEN 1 END) AS consumer_count FROM customers GROUP BY CASE WHEN country IN ('DE', 'UK') THEN 'group_a' ELSE 'other' END, QUARTER(signup_date)) AS x WHERE consumer_count > 6;
